import unittest
from labels import normalize_key, preview_key, import_label


class LabelTests(unittest.TestCase):
    def test_key_contract_and_duplicate_import(self):
        for label, expected in [('Alpha\tBeta', 'alpha-beta'), ('  alpha   beta ', 'alpha-beta'), ('ＡＬＰＨＡ\u2003Beta', 'alpha-beta'), ('Straße', 'strasse')]:
            with self.subTest(label=label):
                self.assertEqual(normalize_key(label), expected)
                self.assertEqual(preview_key(label), expected)
                seen = {'unrelated'}
                self.assertEqual(import_label(label, seen), expected)
                self.assertEqual(seen, {'unrelated', expected})
                with self.assertRaises(ValueError):
                    import_label(label, seen)
                self.assertEqual(seen, {'unrelated', expected})

    def test_blank_rejected_without_mutation(self):
        seen = {'unrelated'}
        with self.assertRaises(ValueError):
            import_label('\u2003\t', seen)
        self.assertEqual(seen, {'unrelated'})


if __name__ == '__main__':
    unittest.main()

