import sqlite3


class AccessDenied(Exception):
    pass


def rename_note(db_path, actor_id, note_id, title):
    with sqlite3.connect(db_path) as connection:
        result = connection.execute('UPDATE notes SET title = ? WHERE id = ?', (title, note_id))
        if result.rowcount == 0:
            raise AccessDenied('note unavailable')

