import unittest
from products import active_products


class ProductTests(unittest.TestCase):
    def test_active_selection_and_missing_flag(self):
        products = [{'id': 1, 'active': True}, {'id': 2, 'active': False}, {'id': 3}]
        self.assertEqual(active_products(products), [products[0]])
        self.assertEqual(products[2], {'id': 3})

    def test_empty(self):
        self.assertEqual(active_products([]), [])


if __name__ == '__main__':
    unittest.main()

