class CsvBuffer:
    def __init__(self):
        self.parts = []

    def write(self, text):
        self.parts.append(text)

    def getvalue(self):
        return ''.join(self.parts)


def export_count(count, sink):
    """Send the count report to the caller's injected sink and return count."""
    sink = CsvBuffer()
    sink.write('count\n' + str(count) + '\n')
    return count

